A.b7e=new B.e(3,"Do they live near here?","","\uadf8\ub4e4\uc740 \uc774 \uadfc\ucc98\uc5d0 \uc0b4\uc544\uc694?","Do",A.O5)
A.beK=new B.e(4,"Does your mom work on Saturday?","","\uc5b4\uba38\ub2c8\ub294 \ud1a0\uc694\uc77c\uc5d0 \uc77c\ud558\uc138\uc694?","Does",A.O4)
A.ba3=new B.e(5,"Do we need an umbrella?","","\uc6b0\ub9ac \uc6b0\uc0b0\uc774 \ud544\uc694\ud574\uc694?","Do",A.O5)
