A.l7R=new B.av(["also, too","noun + \u3082 \xb7 \u79c1\u3082","","I'm going too.","too"])
A.l7t=new B.av(['possessive or linking marker ("\'s", "of")',"noun + \u306e + noun \xb7 \u79c1\u306e\u672c",'Japanese needs \u306e between two nouns where English just stacks them (\u65e5\u672c\u8a9e\u306e\u5148\u751f is "Japanese teacher").',"This is my book.",""])
A.l86=new B.av(["from, since","noun + \u304b\u3089 \xb7 \u4e5d\u6642\u304b\u3089",'The "because" \u304b\u3089 is a different card.',"I work from nine.","from nine"])
A.l64=new B.av(["until, up to","noun + \u307e\u3067 \xb7 \u663c\u307e\u3067","","I slept until noon.","until noon"])
A.l7x=new B.av(["and (a few examples out of many)","noun + \u3084 + noun \xb7 \u30d1\u30f3\u3084\u679c\u7269","\u3068 lists everything, but \u3084 hints there's more than what you named.","I bought bread, fruit and stuff.","bread, fruit"])
A.l6L=new B.av(['question marker ("?")',"end of sentence + \u304b \xb7 \u4f55\u3067\u3059\u304b","","What's this?","What's"])
A.l7e=new B.av(["right?, isn't it? (sharing a feeling)","end of sentence + \u306d \xb7 \u6691\u3044\u3067\u3059\u306d","","It's hot today, isn't it?","isn't it"])
